 while q:
  r,c=q.popleft()
  for dr,dc in steps:
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and grid[rr,cc]==0 and not seen[rr,cc]: seen[rr,cc]=1;q.append((rr,cc))
 return seen
